 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    overall = Counter(v for row in grid for v in row).most_common(1)[0][0]
    sep_rows = []
    sep_colors = []
    for r, row in enumerate(grid):
        color, count = Counter(row).most_common(1)[0]
        if color != overall and count >= 0.8 * w:
            sep_rows.append(r)
            sep_colors.append(color)
    if len(sep_rows) < 2:
        return [[overall]]
    # Separator rows all carry the same grid-line color; deviations mark encoded cells.
    line_color = Counter(sep_colors).most_common(1)[0][0]
    sep_rows = [r for r in sep_rows if Counter(grid[r]).most_common(1)[0][0] == line_color]
    cols = [c for c in range(w) if any(grid[r][c] != line_color for r in sep_rows)]
    vals = [[grid[r][c] for c in cols] for r in sep_rows]
    if len(vals) < 2 or len(cols) < 2:
        return [[overall]]
    out = [[overall for _ in range(len(cols)-1)] for _ in range(len(vals)-1)]
    for r in range(len(vals)-1):
        for c in range(len(cols)-1):
            block = [vals[r][c], vals[r][c+1], vals[r+1][c], vals[r+1][c+1]]
            if block.count(block[0]) == 4:
                out[r][c] = block[0]
    return out
